"""Module dependency composition and root-scoped compilation order.

Call edges make the callee a prerequisite of the caller; pipe edges make the
filter a prerequisite of its target.  A plan's modules are the root plus all
transitive call/pipe prerequisites, prerequisites before dependents, choosing
the lexicographically smallest currently eligible module name.
"""

import heapq
from collections import defaultdict


class DependencyGraph(object):
    """Prerequisite DAG over module names."""

    def __init__(self):
        self.prereqs = defaultdict(set)
        self.names = set()

    def add_node(self, name):
        self.names.add(name)

    def add_call(self, caller, callee):
        """The callee is a prerequisite of the caller."""
        self.names.add(caller)
        self.names.add(callee)
        self.prereqs[caller].add(callee)

    def add_pipe(self, target, filter_name):
        """The filter is a prerequisite of its target."""
        self.names.add(target)
        self.names.add(filter_name)
        self.prereqs[target].add(filter_name)

    def closure(self, root):
        """Root plus all transitive prerequisites."""
        included = set()
        stack = [root]
        while stack:
            name = stack.pop()
            if name in included:
                continue
            included.add(name)
            stack.extend(self.prereqs[name] - included)
        return included

    def compile_order(self, root):
        """Root-scoped module order: prerequisites before dependents."""
        included = self.closure(root)
        indeg = {name: 0 for name in included}
        dependents = defaultdict(list)
        for name in included:
            for dep in self.prereqs[name]:
                if dep in included:
                    dependents[dep].append(name)
                    indeg[name] += 1
        heap = [name for name in included if indeg[name] == 0]
        heapq.heapify(heap)
        order = []
        while heap:
            name = heapq.heappop(heap)
            order.append(name)
            for dep in dependents[name]:
                indeg[dep] -= 1
                if indeg[dep] == 0:
                    heapq.heappush(heap, dep)
        return order


def plan_modules(entry, calls, pipes, module_names):
    """Compilation order of the root's scoped module closure."""
    graph = DependencyGraph()
    for name in module_names:
        graph.add_node(name)
    for (caller, callee) in calls:
        graph.add_call(caller, callee)
    for p in pipes:
        graph.add_pipe(p['target'], p['filter'])
    return graph.compile_order(entry)


def build_applications(entry, pipes_by_target, params):
    """Expand the entry's bound filter applications as a tree.

    Each node is [filter_name, mapping, children] where mapping sends each
    filter parameter name to the entry parameter name it is bound to.  A
    filter reused with different bindings yields different applications.
    """
    roots = []
    stack = [(entry, {name: name for (name, _) in params}, roots)]
    while stack:
        (target, mapping, out) = stack.pop()
        for p in pipes_by_target.get(target, ()):
            fmap = {}
            for (fp, tp) in p['bind'].items():
                fmap[fp] = mapping[tp]
            node = [p['filter'], fmap, []]
            out.append(node)
            stack.append((p['filter'], fmap, node[2]))
    return roots
