"""Deterministic minimum-cost state preparation.

A usable preparation is a path of enabled transitions from the initial state
to the recovered desired state minimizing exactly (sum of costs, number of
commands, command sequence lexicographically).  Command sequences are
canonical interned tries so the lexicographic tie-break is exact without
copying sequences.
"""


class _Seq(object):
    """Interned command-sequence node: parent chain plus one command."""

    __slots__ = ('parent', 'cmd', 'length', 'up')

    def __init__(self, parent, cmd, length):
        self.parent = parent
        self.cmd = cmd
        self.length = length
        up = [parent]
        j = 1
        while (1 << j) <= length:
            up.append(up[j - 1].up[j - 1])
            j += 1
        self.up = up


_ROOT = _Seq(None, None, 0)


def _extend(intern, seq, cmd):
    node = intern.get((seq, cmd))
    if node is None:
        node = _Seq(seq, cmd, seq.length + 1)
        intern[(seq, cmd)] = node
    return node


def _ancestor(node, k):
    bit = 0
    while k:
        if k & 1:
            node = node.up[bit]
        k >>= 1
        bit += 1
    return node


def _seq_cmp(a, b):
    """Compare two equal-length sequences lexicographically."""
    length = a.length
    lo = 0
    hi = length
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if _ancestor(a, length - mid) is _ancestor(b, length - mid):
            lo = mid
        else:
            hi = mid - 1
    if lo == length:
        return 0
    ca = _ancestor(a, length - lo - 1).cmd
    cb = _ancestor(b, length - lo - 1).cmd
    return -1 if ca < cb else (1 if ca > cb else 0)


def _seq_list(seq):
    cmds = []
    node = seq
    while node.parent is not None:
        cmds.append(node.cmd)
        node = node.parent
    cmds.reverse()
    return cmds


def prepare(transitions, initial, target):
    """Minimum-cost preparation, or None when the target is unreachable.

    ``transitions`` is an iterable of (from, to, command, cost) for enabled
    transitions.  Returns (cost, command list) or None.
    """
    if target == initial:
        return (0, [])
    adj = {}
    in_adj = {}
    for (frm, to, cmd, cost) in transitions:
        adj.setdefault(frm, []).append((to, cmd, cost))
        in_adj.setdefault(to, []).append((frm, cmd, cost))
    # Phase 1: plain minimum-cost Dijkstra over states.
    dist = {initial: 0}
    heap = [(0, initial)]
    while heap:
        (d, st) = heapq_pop(heap)
        if d > dist.get(st, _INF):
            continue
        for (to, cmd, cost) in adj.get(st, ()):
            nd = d + cost
            if nd < dist.get(to, _INF):
                dist[to] = nd
                heap.append((nd, to))
                heapq_fix_up(heap)
    if target not in dist:
        return None
    # Phase 2: tight-edge DAG DP minimizing (commands, lexicographic).
    order = sorted(dist.items(), key=lambda item: item[1])
    best = {initial: (0, _ROOT)}
    intern = {}
    for (state, _) in order:
        if state == initial:
            continue
        cand = None
        for (frm, cmd, cost) in in_adj.get(state, ()):
            prev = best.get(frm)
            if prev is None:
                continue
            if dist.get(frm, _INF) + cost != dist[state]:
                continue
            seq = _extend(intern, prev[1], cmd)
            entry = (prev[0] + 1, seq)
            if cand is None:
                cand = entry
            elif entry[0] != cand[0]:
                if entry[0] < cand[0]:
                    cand = entry
            elif _seq_cmp(entry[1], cand[1]) < 0:
                cand = entry
        if cand is not None:
            best[state] = cand
    if target not in best:
        return None
    (hops, seq) = best[target]
    return (dist[target], _seq_list(seq))


# Small local heap helpers keep hot loops self-contained.
import heapq as _hq

_INF = float('inf')


def heapq_pop(heap):
    return _hq.heappop(heap)


def heapq_fix_up(heap):
    _hq.heapify(heap)
